// Process data and prepare results
const predictionObj = $json.prediction || $json;

const predictedTemp = Number(predictionObj.temperature);
const predictedHum  = Number(predictionObj.humidity);
const roomId        = String(predictionObj.room_id);
const targetDate    = new Date(predictionObj.date);
const targetMonth   = targetDate.getMonth() + 1;   // 1–12

// ── Step 1: Statistical thresholds (μ ± 2σ) ──────────────────────────────────

const historicalRows = $('Load Historical Dataset').all();

// First try: same room AND same month (seasonal baseline)
let filteredRows = historicalRows.filter(r => {
  const rowRoom  = String(r.json.room_id) === roomId;
  const rowDate  = new Date(r.json.timestamp);
  const rowMonth = rowDate.getMonth() + 1;
  return rowRoom && rowMonth === targetMonth;
});

// Fallback: same room, all months (if not enough same-month samples)
if (filteredRows.length < 20) {
  filteredRows = historicalRows.filter(r => String(r.json.room_id) === roomId);
}

const temps = filteredRows.map(r => Number(r.json.temperature)).filter(Number.isFinite);
const hums  = filteredRows.map(r => Number(r.json.humidity)).filter(Number.isFinite);

function mean(arr) {
  if (arr.length === 0) return 0;
  return arr.reduce((s, v) => s + v, 0) / arr.length;
}

function stdDev(arr, m) {
  if (arr.length === 0) return 0;
  return Math.sqrt(arr.reduce((s, v) => s + (v - m) ** 2, 0) / arr.length);
}

const tempMean = mean(temps);
const tempStd  = stdDev(temps, tempMean);
const humMean  = mean(hums);
const humStd   = stdDev(hums, humMean);

const THRESHOLD = 2;   // μ ± 2σ

const statTempLower = tempMean - THRESHOLD * tempStd;
const statTempUpper = tempMean + THRESHOLD * tempStd;
const statHumLower  = humMean  - THRESHOLD * humStd;
const statHumUpper  = humMean  + THRESHOLD * humStd;

// ── Step 2: Absolute safety bounds per room ───────────────────────────────────
// Based on ASHRAE 55 and general building standards.
// Room 1 = Kitchen, Room 2 = Data Lab, Room 3 = Mailroom

const SAFETY_BOUNDS = {
  "1": { tempMin: 15, tempMax: 32, humMin: 30, humMax: 75 },   // Kitchen
  "2": { tempMin: 18, tempMax: 27, humMin: 40, humMax: 60 },   // Data Lab (ASHRAE)
  "3": { tempMin: 15, tempMax: 30, humMin: 25, humMax: 65 },   // Mailroom
};

const safety = SAFETY_BOUNDS[roomId] || { tempMin: 10, tempMax: 40, humMin: 20, humMax: 80 };

// ── Step 3: Classify using hybrid rule ───────────────────────────────────────
// A reading is anomalous if it fails the STATISTICAL check OR the SAFETY check.
// The safety check message takes priority for the status label.

function classify(value, statLower, statUpper, safeMin, safeMax) {
  // Safety bounds check
  if (value > safeMax) return "High Anomaly";
  if (value < safeMin) return "Low Anomaly";
  // Statistical bounds check
  if (value > statUpper) return "High Anomaly";
  if (value < statLower) return "Low Anomaly";
  return "Normal";
}

const temperatureStatus = classify(predictedTemp, statTempLower, statTempUpper, safety.tempMin, safety.tempMax);
const humidityStatus    = classify(predictedHum,  statHumLower,  statHumUpper,  safety.humMin,  safety.humMax);

// ── Output ────────────────────────────────────────────────────────────────────

return {
  json: {
    prediction: {
      // Carry forward everything from the prediction node
      ...predictionObj,

      // Anomaly classification
      temperature_status: temperatureStatus,
      humidity_status:    humidityStatus,

      // Statistical bounds (for dashboard display)
      temp_lower: Number(statTempLower.toFixed(2)),
      temp_upper: Number(statTempUpper.toFixed(2)),
      hum_lower:  Number(statHumLower.toFixed(2)),
      hum_upper:  Number(statHumUpper.toFixed(2)),
      temp_mean:  Number(tempMean.toFixed(2)),
      hum_mean:   Number(humMean.toFixed(2)),

      // Safety bounds (for dashboard display)
      safe_temp_min: safety.tempMin,
      safe_temp_max: safety.tempMax,
      safe_hum_min:  safety.humMin,
      safe_hum_max:  safety.humMax,

      // Metadata
      threshold_month:   targetMonth,
      threshold_samples: filteredRows.length,

      // Backend badge — reads from LSTM output if set, falls back to "regression"
      _backendBadge: predictionObj.backend || "regression",
    },
  },
};

