// Process data and prepare results
const p = $json.prediction || $json;

const tempStatus = p.temperature_status;
const humStatus  = p.humidity_status;
const roomId     = String(p.room_id);

const idealTemp = Number(p.temp_mean || 22).toFixed(1);
const idealHum  = Number(p.hum_mean  || 55).toFixed(1);

// ── Room-specific context labels ─────────────────────────────────────────────
const ROOM_CONTEXT = {
  "1": {
    name:    "Kitchen",
    tempHigh: `Reduce temperature toward ${idealTemp}°C. High kitchen temperatures accelerate food spoilage and increase fire risk. Check ventilation and cooling systems.`,
    tempLow:  `Increase temperature toward ${idealTemp}°C. Low temperatures in the kitchen may indicate a heating fault or drafts. Check doors and HVAC settings.`,
    humHigh:  `Reduce humidity toward ${idealHum}% using exhaust fans or dehumidification. High kitchen humidity promotes mould growth and can damage surfaces.`,
    humLow:   `Increase humidity toward ${idealHum}%. Overly dry air in the kitchen can affect food quality and staff comfort. Check ventilation balance.`,
    normal:   `Kitchen conditions are within normal range. Maintain temperature near ${idealTemp}°C and humidity near ${idealHum}%.`,
  },
  "2": {
    name:    "Data Lab",
    tempHigh: `Reduce temperature toward ${idealTemp}°C immediately. Elevated temperatures in the data lab risk hardware overheating and reduced server lifespan. Verify cooling units and airflow.`,
    tempLow:  `Increase temperature toward ${idealTemp}°C. Temperatures below the ASHRAE recommended range (18–27°C) can cause condensation on hardware. Check HVAC set-points.`,
    humHigh:  `Reduce humidity toward ${idealHum}% urgently. Humidity above 60% (ASHRAE limit) risks condensation on circuit boards and corrosion. Activate dehumidification.`,
    humLow:   `Increase humidity toward ${idealHum}%. Very low humidity increases static electricity risk which can damage sensitive lab equipment. Check humidifier settings.`,
    normal:   `Data lab conditions are within ASHRAE-recommended range. Maintain temperature near ${idealTemp}°C and humidity near ${idealHum}%.`,
  },
  "3": {
    name:    "Mailroom",
    tempHigh: `Reduce temperature toward ${idealTemp}°C. Elevated mailroom temperatures can warp packaging materials and damage heat-sensitive contents. Check air conditioning.`,
    tempLow:  `Increase temperature toward ${idealTemp}°C. Cold temperatures in the mailroom may affect adhesives, inks, and sensitive packages. Check heating settings.`,
    humHigh:  `Reduce humidity toward ${idealHum}%. High mailroom humidity causes paper warping, ink bleeding, and packaging degradation. Use dehumidification or improve air circulation.`,
    humLow:   `Increase humidity toward ${idealHum}%. Very dry conditions cause static buildup, paper brittleness, and label adhesion failure. Consider a humidifier.`,
    normal:   `Mailroom conditions are within normal range. Maintain temperature near ${idealTemp}°C and humidity near ${idealHum}%.`,
  },
};

// Fallback context for unknown rooms
const ctx = ROOM_CONTEXT[roomId] || {
  name:     `Room ${roomId}`,
  tempHigh: `Decrease temperature toward ${idealTemp}°C to maintain a comfortable environment.`,
  tempLow:  `Increase temperature toward ${idealTemp}°C to maintain a comfortable environment.`,
  humHigh:  `Decrease humidity toward ${idealHum}% using ventilation or dehumidification.`,
  humLow:   `Increase humidity toward ${idealHum}% to maintain indoor comfort.`,
  normal:   `Conditions are normal. Maintain temperature near ${idealTemp}°C and humidity near ${idealHum}%.`,
};

// ── Build recommendation message ─────────────────────────────────────────────
const tips = [];

if (tempStatus === "High Anomaly") {
  tips.push(ctx.tempHigh);
} else if (tempStatus === "Low Anomaly") {
  tips.push(ctx.tempLow);
}

if (humStatus === "High Anomaly") {
  tips.push(ctx.humHigh);
} else if (humStatus === "Low Anomaly") {
  tips.push(ctx.humLow);
}

// If both are normal, show the normal message
if (tips.length === 0) {
  tips.push(ctx.normal);
}

// ── Output ────────────────────────────────────────────────────────────────────

return {
  json: {
    prediction: {
      // Carry forward everything from anomaly detection
      ...p,

      // Recommendation fields
      recommendation:          tips.join(" "),
      recommended_temperature: Number(idealTemp),
      recommended_humidity:    Number(idealHum),
      room_name:               ctx.name,
    },
  },
};

// Process data and prepare results
function resolveModel() {
  const item = $input.item.json;

  const candidates = [
    item.model,
    item.Model,
    item.lstm,
    item.LSTM,
  ];

  // Scan all input fields in case model is stored under another name
  for (const key of Object.keys(item)) {
    if (item[key] && typeof item[key] === "object") {
      candidates.push(item[key]);
    }
  }

  for (const candidate of candidates) {
    if (!candidate || typeof candidate !== "object") continue;

    const schema = candidate.schema;

    if (
      schema === "ridge-fourier-v2" ||
      schema === "ridge-fourier-v1" ||
      schema === "lstm-v1"
    ) {
      return candidate;
    }
  }

  throw new Error(
    "No trained model found. Available input fields: " +
    Object.keys(item).join(", ")
  );
}

function daysBetween(dateA, dateB) {
  const a = Date.UTC(dateA.getFullYear(), dateA.getMonth(), dateA.getDate());
  const b = Date.UTC(dateB.getFullYear(), dateB.getMonth(), dateB.getDate());
  return Math.round((b - a) / 86400000);
}

// ===============================
// RIDGE REGRESSION PATH
// ===============================

function buildFeatureRow(date) {
  const hour = date.getUTCHours() + date.getUTCMinutes() / 60;
  const yearStart = Date.UTC(date.getUTCFullYear(), 0, 0);
  const doy = (date.getTime() - yearStart) / 86400000;
  const dow = ((date.getUTCDay() + 6) % 7) + hour / 24;

  const f = [];

  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * hour / 24));
    f.push(Math.cos(2 * Math.PI * k * hour / 24));
  }

  for (const k of [1, 2, 3]) {
    f.push(Math.sin(2 * Math.PI * k * doy / 365.25));
    f.push(Math.cos(2 * Math.PI * k * doy / 365.25));
  }

  for (const k of [1, 2]) {
    f.push(Math.sin(2 * Math.PI * k * dow / 7));
    f.push(Math.cos(2 * Math.PI * k * dow / 7));
  }

  return f;
}

function ridgePredict(model, target, room) {
  const roomKey = String(room);
  const features = buildFeatureRow(target);

  function predictOne(targetName) {
    let coef;
    let intercept;

    if (model.schema === "ridge-fourier-v2") {
      coef = model.coefficients?.[targetName]?.[roomKey];
      intercept = model.intercepts?.[targetName]?.[roomKey];
    } else {
      if (targetName !== "temperature") return null;
      coef = model.coefficients?.[roomKey];
      intercept = model.intercepts?.[roomKey];
    }

    if (!coef || intercept === undefined || intercept === null) return null;

    let prediction = intercept;

    for (let i = 0; i < coef.length; i++) {
      prediction += coef[i] * features[i];
    }

    return Number(prediction.toFixed(3));
  }

  return {
    temperature: predictOne("temperature"),
    humidity: predictOne("humidity"),
  };
}

// ===============================
// LSTM PATH
// ===============================

function vecMatMul(vec, flatMat, cols) {
  const out = new Array(cols).fill(0);

  for (let j = 0; j < cols; j++) {
    for (let i = 0; i < vec.length; i++) {
      out[j] += vec[i] * flatMat[i * cols + j];
    }
  }

  return out;
}

function sigmoid(x) {
  return 1 / (1 + Math.exp(-x));
}

function clamp(x, lo, hi) {
  return Math.max(lo, Math.min(hi, x));
}

function lstmStep(x, h, c, W, U, b, units) {
  const g4 = units * 4;

  const xW = vecMatMul(x, W, g4);
  const hU = vecMatMul(h, U, g4);

  const z = b.map((bv, i) => xW[i] + hU[i] + bv);

  const iGate = z.slice(0, units).map(sigmoid);
  const fGate = z.slice(units, 2 * units).map(sigmoid);
  const cGate = z.slice(2 * units, 3 * units).map(Math.tanh);
  const oGate = z.slice(3 * units, 4 * units).map(sigmoid);

  const cNew = c.map((cv, i) => fGate[i] * cv + iGate[i] * cGate[i]);
  const hNew = cNew.map((cv, i) => oGate[i] * Math.tanh(cv));

  return {
    h: hNew,
    c: cNew,
  };
}

function lstmForward(sequence, W, U, b, units) {
  let h = new Array(units).fill(0);
  let c = new Array(units).fill(0);

  for (const x of sequence) {
    const step = lstmStep(x, h, c, W, U, b, units);
    h = step.h;
    c = step.c;
  }

  return h;
}

function denseForward(h, Wd, bd) {
  const out = bd.slice();

  for (let j = 0; j < bd.length; j++) {
    for (let i = 0; i < h.length; i++) {
      out[j] += h[i] * Wd[i * bd.length + j];
    }
  }

  return out;
}

function inverseScale(v, min, max) {
  return v.map((val, i) => {
    return clamp(val, 0, 1) * (max[i] - min[i]) + min[i];
  });
}

function lstmPredict(model, target, room) {
  const roomKey = String(room);
  const roomData = model.room_data?.[roomKey];

  if (!roomData) {
    const available = Object.keys(model.room_data || {}).join(", ");
    throw new Error(`LSTM: no data for room_id=${room}. Available rooms: ${available}`);
  }

  const {
    units,
    W,
    U,
    b,
    Wd,
    bd,
    scaler_min,
    scaler_max,
    last_date,
    last_seq,
  } = roomData;

  if (!last_seq || !Array.isArray(last_seq)) {
    throw new Error("LSTM model is missing last_seq data.");
  }

  const lastDate = new Date(last_date + "T00:00:00");

  const steps = Math.min(
    Math.max(0, daysBetween(lastDate, target)),
    365 * 3
  );

  let buffer = last_seq.map(row => row.slice());

  for (let i = 0; i < steps; i++) {
    const hFinal = lstmForward(buffer, W, U, b, units);

    const scaled = denseForward(hFinal, Wd, bd).map(v =>
      clamp(v, 0, 1)
    );

    buffer = buffer.slice(1).concat([scaled]);
  }

  const [temperature, humidity] = inverseScale(
    buffer[buffer.length - 1],
    scaler_min,
    scaler_max
  );

  return {
    temperature: Number(temperature.toFixed(2)),
    humidity: Number(humidity.toFixed(2)),
  };
}

// ===============================
// MAIN
// ===============================

const item = $input.item.json;
const model = resolveModel();

const rawDate =
  item.timestamp ||
  item.date ||
  item.query?.timestamp ||
  item.query?.date ||
  new Date().toISOString();

const target = new Date(rawDate);

if (isNaN(target.getTime())) {
  throw new Error(`Invalid date/timestamp: ${rawDate}`);
}

const room = Number(
  item.room_id ||
  item.query?.room_id ||
  item.body?.room_id ||
  (model.rooms || [1])[0]
);

if (!model.rooms || !model.rooms.includes(room)) {
  throw new Error(
    `Unknown room_id ${room}. Model trained on: ${(model.rooms || []).join(", ")}`
  );
}

let result;
let backend;

if (model.schema === "lstm-v1") {
  result = lstmPredict(model, target, room);
  backend = "lstm";
} else {
  result = ridgePredict(model, target, room);
  backend = "regression";
}

const dataEnd = model.data_range?.end
  ? new Date(model.data_range.end)
  : target;

const daysPast = Math.max(
  0,
  (target.getTime() - dataEnd.getTime()) / 86400000
);

return {
  json: {
    ...item,

    room_id: room,
    timestamp: target.toISOString(),

    predicted_temperature: result.temperature,
    predicted_humidity: result.humidity,

    latest_temperature: result.temperature,
    latest_humidity: result.humidity,

    prediction_model: backend,
    model_schema: model.schema,
    extrapolation_days: Math.round(daysPast),

    prediction: {
      temperature: result.temperature,
      humidity: result.humidity,
      room_id: room,
      date: target.toISOString(),
      backend,
      model_schema: model.schema,
      model_data_range: model.data_range || null,
      extrapolation_days: Math.round(daysPast),
    },
  },
};
